                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.type === 'password' ? (
                  <div className="password-input-wrapper">
                    <input
                      type={showRegisterPassword ? 'text' : 'password'}
                      value={formData[field.key] || ''}
                      onChange={(e) => handleInputChange(field.key, e.target.value)}
                      placeholder={field.placeholder}
                      className="input-field"
                    />
                    <button 
                      type="button" 
                      className="password-toggle-btn" 
                      onClick={() => setShowRegisterPassword(!showRegisterPassword)}
                    >
                      {showRegisterPassword ? '👁️‍🗨️' : '👁️'}
                    </button>
                  </div>
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="input-field"
                  />
                )}
              </div>
            ))}
          </div>

          <div className="registration-actions landscape-actions">
            <button
              onClick={saveCompleteProfile}
              disabled={isLoading}
              className="btn-save-profile"
            >
              {isLoading ? '⏳ Saving...' : 'Continue'}
            </button>
            <button
              onClick={() => {
                addNotification('⏭️ Profile skipped. You can complete it later.');
                addToConversation('📱 You', 'details#(skipped)', false);
                addToConversation('🤖 System', SYSTEM_MESSAGES.detailsNotProvided, true);
                setSystemResponseMessage(SYSTEM_MESSAGES.detailsNotProvided);
                setShowSystemResponse(true);
                setCurrentStep(4);
                setIsCompleteProfileStep(false);
              }}
              className="btn-skip"
            >
              Skip
            </button>
            <button onClick={handleLogout} className="btn-exit">
              Exit
            </button>
          </div>

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION STEPS - Step 2 & 4
  // ============================================
  const renderRegistrationStep = () => {
    const step = currentStep + 1;
    const isLastStep = step === 4;
    const isStepCompleted = completedSteps.has(step - 1);

    const getFields = () => {
      if (step === 2) {
        return [
          { key: 'phone_number', label: '📱 Phone Number', placeholder: 'e.g. 0712345678', type: 'tel' },
          { key: 'name', label: '👤 Full Name', placeholder: 'e.g. John Doe', type: 'text' },
          { key: 'password', label: '🔑 Password (min 10 chars, letters & numbers/symbols)', placeholder: 'Enter your password', type: 'password' },
          { key: 'age', label: '🎂 Age', placeholder: 'e.g. 25', type: 'number' },
          { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female'] },
          { key: 'county', label: '📍 County', type: 'select-with-search', options: KENYAN_COUNTIES },
          { key: 'town', label: '🏙️ Town/City', type: 'select-with-search', options: [] }
        ];
      }
      if (step === 4) {
        return [
          { key: 'description', label: '💭 Describe yourself', placeholder: 'Write a short description about yourself...', type: 'textarea' }
        ];
      }
      return [];
    };

    const getTownsForCounty = (county) => {
      return KENYAN_TOWNS[county] || [];
    };

    const handleCountyChange = (value) => {
      handleInputChange('county', value);
      handleInputChange('town', '');
    };

    const fields = getFields();
    const stepTitles = {
      2: 'Create Your Dating Profile',
      4: 'Tell Us About Yourself'
    };
    const stepMessages = {
      2: 'Complete your registration details to start meeting compatible partners.',
      4: ''
    };
    const stepIcons = {
      2: '📝',
      4: '💭'
    };

    return (
      <div className="registration-container landscape">
        <div className="registration-card landscape-card">
          <div className="registration-header landscape-header">
            <span className="registration-icon">{stepIcons[step]}</span>
            <div className="header-text">
              <h1>{stepTitles[step]}</h1>
              {stepMessages[step] && <p className="subtitle">{stepMessages[step]}</p>}
            </div>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {currentStep === 1 ? '1/4' : currentStep === 3 ? '2/4' : `${completedSteps.size}/4`}</span>
            </div>
          )}

          {showSystemResponse && systemResponseMessage && (
            <div className="system-response-card">
              <div className="response-title">📨 System Response</div>
              <div className="response-body" style={{ whiteSpace: 'pre-line' }}>{systemResponseMessage}</div>
            </div>
          )}

          <div className="step-info-card landscape-step-info">
            <div className="step-number">Step {step} of 4</div>
            <h2>{stepTitles[step]}</h2>
            {stepMessages[step] && <p>{stepMessages[step]}</p>}
          </div>

          {registrationError && !userExistsError && (
            <div className="registration-error">
              <span className="error-icon">⚠️</span>
              <span className="error-text">{registrationError}</span>
            </div>
          )}

          {fields.length > 0 && (
            <div className="registration-form landscape-form">
              {fields.map((field) => {
                if (field.key === 'town') {
                  const towns = getTownsForCounty(formData.county);
                  return (
                    <div key={field.key} className="input-group landscape-input-group">
                      <label>{field.label}</label>
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        className="input-field"
                        disabled={!formData.county}
                      >
                        <option value="">{formData.county ? 'Select Town' : 'Select County First'}</option>
                        {towns.map(town => (
                          <option key={town} value={town}>{town}</option>
                        ))}
                      </select>
                      {!formData.county && (
                        <small className="field-hint">Please select a county first to see towns</small>
                      )}
                    </div>
                  );
                }

                if (field.key === 'county') {
                  return (
                    <div key={field.key} className="input-group landscape-input-group">
                      <label>{field.label}</label>
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleCountyChange(e.target.value)}
                        className="input-field"
                      >
                        <option value="">Select County</option>
                        {KENYAN_COUNTIES.map(county => (
                          <option key={county} value={county}>{county}</option>
                        ))}
                      </select>
                    </div>
                  );
                }

                if (field.type === 'select') {
                  return (
                    <div key={field.key} className="input-group landscape-input-group">
                      <label>{field.label}</label>
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        className="input-field"
                        required
                      >
                        <option value="">Select {field.label}</option>
                        {field.options.map(opt => (
                          <option key={opt} value={opt}>{opt}</option>
                        ))}
                      </select>
                    </div>
                  );
                }

                if (field.type === 'textarea') {
                  return (
                    <div key={field.key} className="input-group landscape-input-group full-width">
                      <label>{field.label}</label>
                      <textarea
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        placeholder={field.placeholder}
                        className="textarea-field"
                        rows={4}
                        required
                      />
                    </div>
                  );
                }

                return (
                  <div key={field.key} className="input-group landscape-input-group">
                    <label>{field.label}</label>
                    <input
                      type={field.type || 'text'}
                      value={formData[field.key] || ''}
                      onChange={(e) => handleInputChange(field.key, e.target.value)}
                      placeholder={field.placeholder}
                      className="input-field"
                      required
                    />
                  </div>
                );
              })}
            </div>
          )}

          <div className="registration-actions landscape-actions">
            <button
              onClick={() => {
                const allFilled = fields.every(f => {
                  if (f.key === 'town' && !formData.county) return true;
                  return formData[f.key] && formData[f.key].trim() !== '';
                });
                if (!allFilled && step !== 4) {
                  addNotification('⚠️ Please fill in all fields.', 'warning');
                  return;
                }
                goToNextStep();
              }}
              disabled={isLoading}
              className="btn-register"
            >
              {isLoading ? '⏳ Processing...' : 
               step === 3 ? 'Next ➡' :
               isLastStep && isStepCompleted ? 'Complete ✓' :
               'Continue'}
            </button>
            <button onClick={handleLogout} className="btn-exit">
              Exit
            </button>
          </div>

          {isLastStep && isStepCompleted && (
            <div className="registration-complete-prompt">
              <p>🎉 Registration complete! You can now search for matches.</p>
            </div>
          )}

          {responseMessage && (
            <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
              {responseMessage}
            </div>
          )}

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER NOTIFICATIONS
  // ============================================
  const renderNotifications = () => {
    if (notifications.length === 0) return null;
    return (
      <div className="notifications-container">
        {notifications.map((notif) => (
          <div key={notif.id} className={`notification ${notif.type || 'success'}`}>
            {notif.message}
          </div>
        ))}
      </div>
    );
  };

  // ============================================
  // RENDER PROFILE MODAL
  // ============================================
  const renderProfileModal = () => {
    if (!selectedMatch || !showMatchDetails) return null;

