                <div className="profile-item"><span className="label">👤 Name</span><span>{currentUser.name}</span></div>
                <div className="profile-item"><span className="label">🎂 Age</span><span>{currentUser.age}</span></div>
                <div className="profile-item"><span className="label">⚤ Gender</span><span>{currentUser.gender || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">📍 County</span><span>{currentUser.county || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🏙️ Town</span><span>{currentUser.town || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">💼 Profession</span><span>{currentUser.profession || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🎓 Education</span><span>{currentUser.education || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">💍 Marital Status</span><span>{currentUser.marital_status || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🙏 Religion</span><span>{currentUser.religion || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{currentUser.ethnicity || 'Not specified'}</span></div>
                {currentUser.description && (
                  <div className="profile-item full-width">
                    <span className="label">💭 About Me</span>
                    <span>{currentUser.description}</span>
                  </div>
                )}
              </div>
              <div className="modal-actions" style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                <div style={{ display: 'flex', gap: '10px', justifyContent: 'center' }}>
                  <button type="button" className="btn-primary" onClick={startEditProfile}>
