            <div className="stat-label">Total Matches</div>
          </div>
          <div className="stat-card requests clickable" onClick={() => handleStatClick('pendingRequests')}>
            <span className="stat-icon">📬</span>
            <div className="stat-number">{stats.pendingRequests}</div>
            <div className="stat-label">Pending Requests</div>
          </div>
          <div className="stat-card accepted clickable" onClick={() => handleStatClick('acceptedMatches')}>
            <span className="stat-icon">💕</span>
            <div className="stat-number">{stats.acceptedMatches}</div>
            <div className="stat-label">Accepted Matches</div>
          </div>
          <div className="stat-card messages clickable" onClick={() => handleStatClick('unreadMessages')}>
            <span className="stat-icon">💬</span>
            <div className="stat-number">{stats.unreadMessages}</div>
            <div className="stat-label">Unread Messages</div>
          </div>
        </div>

        <nav className="dashboard-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('discover');
              if (allMatches.length === 0) {
                const userGender = currentUser?.gender;
                let sampleData = [];

                if (userGender && userGender.toLowerCase() === 'male') {
                  sampleData = SAMPLE_MATCHES;
                } else if (userGender && userGender.toLowerCase() === 'female') {
                  sampleData = SAMPLE_MALE_MATCHES;
                } else {
                  sampleData = [...SAMPLE_MATCHES, ...SAMPLE_MALE_MATCHES];
                }

                setAllMatches(sampleData.slice(0, 3));
                setMatchResults(sampleData);
                setHasMoreMatches(sampleData.length > 3);
                setMatchSearchActive(true);
              }
            }}
          >
            🔍 Discover
            <span className="nav-badge">{allMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('matches');
              if (myMatches.length === 0) {
                setMyMatches(SAMPLE_MY_MATCHES);
              }
            }}
          >
            💕 Matches
            <span className="nav-badge">{myMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('requests');
              if (incomingRequests.length === 0) {
                setIncomingRequests(SAMPLE_REQUESTS);
              }
            }}
          >
            📬 Requests
            {hasRequests && <span className="nav-badge red">{incomingRequests.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('chat');
            }}
          >
            💬 Chat
            {hasChatContacts && <span className="nav-badge">{chatContacts.length}</span>}
          </button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && renderDiscoverTable()}
          {activeTab === 'matches' && renderMyMatchesTable()}
          {activeTab === 'requests' && renderRequestsTable()}
          {activeTab === 'chat' && (
            <div className="chat-container-whatsapp">
              {renderChat()}
            </div>
          )}
        </main>

        {showMatchDetails && renderProfileModal()}
        {showProfile && renderProfileDetails()}
        {renderDescriptionModal()}
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================
  return (
    <div className="app">
      {renderNotifications()}
      {renderLogoutModal()}


      {/* Removed media-viewer-lite as per new in-place zoom design */}

      {showSuccessScreen ? (
        renderSuccessScreen()
      ) : userExistsError ? (
        renderUserExistsWarning()
      ) : showWelcomeBack && !isLoggedIn ? (
        renderWelcomeBack()
      ) : isLoggedIn ? (
        currentView === 'reactivation' ? renderReactivationPage() :
        showMainMenu ? renderMainMenu() : renderDashboard()
      ) : currentView === 'login' ? (
        renderLoginPage()
      ) : (
        /* Activation / Registration flow */
        activationDone ? (
          isCompleteProfileStep ? (
            renderCompleteProfile()
          ) : (
            renderRegistrationStep()
          )
        ) : (
          renderActivationPage()
        )
      )}
    </div>
  );
}

export default App;
